export function PositionSticky({
  topOffset = {{topOffset}},
  headerColor = "{{headerColor}}",
  containerHeight = {{containerHeight}},
  label = "{{label}}",
}) {
  const row = { padding: "14px 12px", borderTop: "1px solid #24143022", fontSize: 12 };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 300 }}
      role="img" aria-label="A scrollable list with a sticky header; scroll the list below and the header stays pinned once it reaches its top offset">
      <div style={{ height: containerHeight, overflow: "auto", border: "1.5px solid #24143055", borderRadius: 8, background: "#FAF7F2" }}>
        <div style={{ position: "sticky", top: topOffset, background: headerColor, padding: "8px 12px", fontWeight: 700, fontSize: 12, color: "#241430" }}>
          {label}
        </div>
        <div style={row}>Row one</div><div style={row}>Row two</div><div style={row}>Row three</div>
        <div style={row}>Row four</div><div style={row}>Row five</div><div style={row}>Row six</div><div style={row}>Row seven</div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        position: sticky; top: {topOffset}px &mdash; scroll the list to see the header lock in place
      </p>
    </div>
  );
}
